const account='tomas.kocner@wofevents.com';
const clean=(v,n)=>String(v??'').replace(/\s+/g,' ').trim().slice(0,n);
const address=(from)=>{if(typeof from==='string')return clean(from,500);const first=from?.value?.[0];return clean(first?.name?first.name+' <'+first.address+'>':first?.address||from?.text,500)};
return items.map(({json})=>{const messageId=clean(json.messageId||json.headers?.['message-id']||json.headers?.messageId,500);const rawDate=json.date||json.receivedDate||json.headers?.date;const date=new Date(rawDate);if(!messageId||Number.isNaN(date.getTime()))return null;return {json:{sourceAccount:account,messageId,threadId:clean(json.threadId||messageId,500),subject:clean(json.subject||'(bez predmetu)',500),sender:address(json.from),timestamp:date.toISOString(),preview:clean(json.text||json.textPlain||json.html||'',2000),url:'',important:false}}}).filter(Boolean);
